const assert = require('node:assert');
const { parseCsv } = require('./csv.js');
const { names } = require('./report.js');

// basic rows
assert.deepStrictEqual(
  parseCsv('name,qty\napple,3\nbanana,5\n'),
  [{ name: 'apple', qty: '3' }, { name: 'banana', qty: '5' }]
);

// quoted field containing a comma
assert.deepStrictEqual(
  parseCsv('name,note\nwidget,"a, b"\n'),
  [{ name: 'widget', note: 'a, b' }]
);

// escaped double-quote inside a quoted field
assert.deepStrictEqual(
  parseCsv('name,note\nwidget,"say ""hi"""\n'),
  [{ name: 'widget', note: 'say "hi"' }]
);

// header only / empty
assert.deepStrictEqual(parseCsv('name,qty\n'), []);
assert.deepStrictEqual(parseCsv(''), []);

// consumed by report.names, with a quoted comma in the name
assert.deepStrictEqual(names('name,qty\n"a, b",1\nc,2\n'), ['a, b', 'c']);

console.log('ok');

